import {
  isReactive,
  isShallow,
  shallowReadArray,
  toReactive,
} from '@vue/reactivity'

const sourceIsReactiveArray = sourceIsArray && isReactive(source)
const sourceIsShallowReactiveArray =
  sourceIsReactiveArray && isShallow(source)
if (sourceIsReactiveArray) {
  source = shallowReadArray(source)
}
ret = new Array(source.length)
for (let i = 0, l = source.length; i < l; i++) {
  ret[i] = renderItem(
    sourceIsReactiveArray && !sourceIsShallowReactiveArray
      ? toReactive(source[i])
      : source[i],
    i,
    undefined,
    cached && cached[i],
  )
}

