import { renderList } from '../../src/helpers/renderList'
import { shallowReactive, ref } from '@vue/reactivity'
import { isReactive } from '../../src/vnode'

describe('verify shallowReactive v-for', () => {
  test('shallowReactive array items are not converted', () => {
    const arr = shallowReactive([{ aaa: ref('aaa1') }])
    let result: any
    renderList(arr as any, (item: any) => {
      result = item
      return null
    })
    expect(typeof result.aaa).toBe('object')
    expect(isReactive(result)).toBe(false)
  })
  test('reactive array items still converted', () => {
    const arr = [{ aaa: ref('aaa1') }]
    let result: any
    renderList(arr as any, (item: any) => {
      result = item
      return null
    })
    expect(isReactive(result)).toBe(true)
  })
})
EOF
